insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('3333dc5a-7e11-4ba7-8cc0-9bcb53b8a728', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$inleiding — glucose omzetting in gistcellen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context1.png$$,
   $$Wijn wordt gemaakt uit druivensap waaraan gist wordt toegevoegd. In de gistcellen vinden verschillende reacties plaats. Bij een van die reacties wordt glucose uit druivensap omgezet tot koolstofdioxide en ethanol.$$, 'inline'),
  ('4861aa0a-cdbd-414d-a125-c00c36fd7787', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$figuur 1 — structuurformules glutathion-3-MH en 3-MH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context2.png$$,
   $$Sauvignon blanc is een witte wijn met een passievruchtaroma. Dit aroma wordt onder meer veroorzaakt door de stof 3-MH. De stof 3-MH is niet aanwezig in druivensap, maar wordt door gistcellen gevormd uit de geurloze stof glutathion-3-MH. In figuur 1 zijn de structuurformules van glutathion-3-MH en 3-MH gegeven.
figuur 1: structuurformule van glutathion-3-MH (een tripeptide van glutaminezuur, cysteïne en glycine, waarbij de restgroep van cysteïne via een S-atoom is gekoppeld aan een CH₃-CH₂-CH₂-CH(-CH₂-CH₂-OH)-keten) en van 3-MH (dezelfde CH₃-CH₂-CH₂-CH(-CH₂-CH₂-OH)-keten met een vrije SH-groep).$$, 'inline'),
  ('f1bd2246-0964-41a8-b5a1-70a1fd4d638a', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$opbouw tripeptide en koppeling eerste aminozuur-eenheid$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context3.png$$,
   $$Glutathion-3-MH is opgebouwd uit een tripeptide en een molecuul 3-MH. De laatste twee eenheden van het tripeptide zijn een cysteïne- en een glycine-eenheid.
De eerste aminozuur-eenheid van het tripeptide is anders gekoppeld dan de andere eenheden. Bij deze aminozuur-eenheid is de restgroep via een peptidebinding gekoppeld aan de cysteïne-eenheid.$$, 'inline'),
  ('e1baffcb-0c24-4c92-ae79-34c1113813fa', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$figuur 2 en enzym-premisse — omzetting in drie stappen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context4.png$$,
   $$De omzetting van glutathion-3-MH naar 3-MH vindt plaats in drie stappen (figuur 2).
figuur 2: reactieschema glutathion-3-MH → (stap 1) → 3-MH-Cys-Gly → (stap 2) → 3-MH-Cys → (stap 3) → 3-MH.
Deze stappen vinden plaats onder invloed van enzymen.$$, 'inline'),
  ('18f7b2bf-c66b-4774-855d-c6a1e3bdc17f', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$scheiding gist van wijn — bezinken en afschenken$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context5.png$$,
   $$Na het vergisten wordt de gist door middel van bezinken en afschenken gescheiden van de wijn. Dit proces zou sneller uitgevoerd kunnen worden door een andere scheidingsmethode toe te passen. Deze methode berust op hetzelfde verschil in stofeigenschap als bezinken.$$, 'inline'),
  ('812b1214-94ba-4adf-8934-d8a45524f4aa', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$figuur 3 — structuurformules 3-MHA en 3-MH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context6.png$$,
   $$In sauvignon blanc is nog een andere stof aanwezig die bijdraagt aan het passievruchtaroma: 3-MHA (figuur 3). De stof 3-MHA is de ester van 3-MH en één andere stof.
figuur 3: structuurformules van 3-MHA (CH₃-CH₂-CH₂-CH(-S-H)-CH₂-CH₂-O-C(=O)-CH₃) en 3-MH (CH₃-CH₂-CH₂-CH(-S-H)-CH₂-CH₂-OH).$$, 'inline'),
  ('593e81be-6c9d-40e5-bd78-85df5f30f1ee', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$hydrolyse 3-MHA tijdens opslag — verwijzing uitwerkbijlage$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context7.png$$,
   $$Tijdens de opslag van de wijn kan hydrolyse van 3-MHA plaatsvinden. Op de uitwerkbijlage is de hydrolyse van 3-MHA onvolledig weergegeven.$$, 'inline'),
  ('b08e4f23-ea55-4d12-bed1-58f120cc7b70', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$geurdrempel — definitie en waarden 3-MHA/3-MH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context8.png$$,
   $$Om een geurstof in wijn te kunnen waarnemen, moet de geurdrempel van die geurstof worden overschreden. De geurdrempel wordt hier gedefinieerd als de minimale concentratie die de geurstof in wijn moet hebben om door mensen waargenomen te kunnen worden. De geurdrempel van 3-MHA is 4,0 ng L⁻¹ en de geurdrempel van 3-MH is 60 ng L⁻¹.$$, 'inline'),
  ('232408e5-d8aa-4694-bffb-ccccd5ff86f7', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$hypothese Danilo — geurdrempel en oplosbaarheid$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context9.png$$,
   $$Havoleerling Danilo formuleert de volgende hypothese: De geurdrempel van een geurstof in wijn is hoger naarmate de geurstof beter in de wijn oplost. Wijn bestaat voor het grootste deel uit water.$$, 'inline'),
  ('11e20b9f-1a2b-4788-ae01-ee9342306d2f', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$formule — Odour Activity Value (OAV)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context10.png$$,
   $$Hoe sterk het passievruchtaroma in wijn wordt waargenomen, kan worden berekend met de Odour Activity Value (OAV).
OAV = (concentratie van de geurstof in wijn) / (geurdrempel van de geurstof in de wijn)$$, 'inline'),
  ('2aadae01-859b-4453-ab4e-dea7c5c7ce71', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$tabel 1 — concentraties, geurdrempels en OAV 3-MH/3-MHA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context11.png$$,
   $$In tabel 1 staan gegevens over de concentraties 3-MH en 3-MHA in een bepaalde fles sauvignon blanc.
tabel 1: geurstof — concentratie in vloeistof (ng/L) — geurdrempel (ng/L) — OAV. 3-MHA: 2,50·10³ ng/L; 4,0 ng/L; 6,3·10². 3-MH: 1,80·10⁴ ng/L; 60 ng/L; 3,0·10².$$, 'inline'),
  ('caf9d3f1-1365-4986-bfae-4b0392449c5e', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$totale OAV en omzetting 3-MHA naar 3-MH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context12.png$$,
   $$De totale OAV van 3-MH en 3-MHA bij elkaar opgeteld is volgens tabel 1 gelijk aan 9,3·10². Wanneer sauvignon blanc lang bewaard wordt, zal het passievruchtaroma minder sterk worden. Een oorzaak hiervan is de omzetting van 3-MHA tot 3-MH. De totale OAV neemt hierdoor af.
Na een bepaalde tijd is 50% van de 3-MHA in tabel 1 omgezet tot 3-MH.$$, 'inline'),
  ('0feed504-c1d2-4678-8433-d98fb531a35e', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', $$uitwerkbijlage vraag 5 — onvolledige hydrolysevergelijking 3-MHA/3-MH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-context13.png$$,
   $$onvolledige hydrolysevergelijking op de uitwerkbijlage: 3-MHA (structuurformule CH₃-CH₂-CH₂-CH(-S-H)-CH₂-CH₂-O-C(=O)-CH₃) reageert met een stippellijn (in te vullen stof) tot een pijl naar de (in te vullen) producten; daaronder is apart de structuurformule van 3-MH (CH₃-CH₂-CH₂-CH(-S-H)-CH₂-CH₂-OH) afgebeeld met een stippellijn erachter (+ in te vullen stof); de leerling moet beide vergelijkingen met structuurformules voor koolstofverbindingen aanvullen.$$, 'uitwerkbijlage'),
  ('afa05bbe-42eb-4e38-afae-75728dcfadaa', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$inleiding — hoogovenwand en magnesiumoxide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context1.png$$,
   $$In hoogovens wordt ijzererts omgezet tot vloeibaar ijzer. De wanden van hoogovens moeten dus bestand zijn tegen zeer hoge temperaturen. Deze wanden worden daarom gemaakt van een hittebestendige stof zoals magnesiumoxide (MgO).$$, 'inline'),
  ('8b3ace26-e5f3-4634-b498-f0a4e493d4ed', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$bischofiet MgCl2·6H2O — oplossen in water$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context2.png$$,
   $$Magnesiumoxide wordt gemaakt uit bischofiet: MgCl₂·6H₂O. Bischofiet is een vaste stof die kan worden gewonnen uit een meters dikke bischofiet-laag die zich op ongeveer anderhalve kilometer onder de grond bevindt. Door een metalen buis wordt water in deze laag geïnjecteerd. Het bischofiet lost hierin op.$$, 'inline'),
  ('0d74e5c4-65b2-4b98-885b-be323d4bc1fe', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$figuur 1 — dwarsdoorsnede caverne en dak-olie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context3.png$$,
   $$Doordat het bischofiet oplost, ontstaat een ruimte die caverne wordt genoemd. Deze caverne is gevuld met een oplossing van magnesiumchloride (MgCl₂). Op deze oplossing wordt een vloeistoflaag aangebracht die dak-olie wordt genoemd. De dak-olie voorkomt dat de zoutlagen boven de bischofiet-laag oplossen, zie figuur 1.
figuur 1: dwarsdoorsnede van de ondergrond met bovenste grondlaag, zoutlagen, dak-olie, caverne (gevuld met MgCl₂-oplossing) en de bischofiet-laag; via een dubbele buis wordt water (H₂O) naar beneden gepompt en komt MgCl₂-oplossing weer naar boven.$$, 'inline'),
  ('677e50c5-dca6-4489-bff3-cbdab0e8d0e2', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$stoffen onderzocht als dak-olie — ethaan-1,2-diol ongeschikt$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context4.png$$,
   $$Een aantal stoffen is onderzocht op bruikbaarheid als dak-olie. Ethaan-1,2-diol is ook onderzocht, maar bleek ongeschikt.$$, 'inline'),
  ('3fcd103b-4824-4d90-be6e-08c9590d3103', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$halfreacties a en b — corrosie metalen buis (sulfiet/zuurstof)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context5.png$$,
   $$Doordat in het water een kleine hoeveelheid zuurstof is opgelost, kan corrosie van de metalen buis optreden. Aan het water wordt daarom een kleine hoeveelheid natriumsulfiet-oplossing (Na₂SO₃) toegevoegd, waardoor corrosie wordt verhinderd. In de buis treden de volgende halfreacties op:
SO₃²⁻ + H₂O → SO₄²⁻ + 2 H⁺ + 2 e⁻ (halfreactie a)
O₂ + 2 H₂O + 4 e⁻ → 4 OH⁻ (halfreactie b)$$, 'inline'),
  ('0f24c2b8-9d3b-4831-96be-54072fe8f1aa', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$premisse — pH verandert niet bij sulfiet/sulfaat omzetting$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context6.png$$,
   $$Bij de omzetting van sulfiet tot sulfaat blijkt de pH van de oplossing in de buis niet te veranderen.$$, 'inline'),
  ('410be582-ead4-41cf-b515-d35584f8d00d', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$reactie 1 — dolime met MgCl2-oplossing tot Mg(OH)2 en CaCl2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context7.png$$,
   $$De MgCl₂-oplossing die uit de bodem wordt gewonnen, wordt verzameld in bezinkbakken. Aan de MgCl₂-oplossing wordt de vaste stof dolime toegevoegd. Dolime is een mengsel van de stoffen calciumoxide en magnesiumoxide. Wanneer dolime aan de MgCl₂-oplossing wordt toegevoegd, treedt reactie 1 op. Door reactie 1 ontstaan de vaste stof magnesiumhydroxide (Mg(OH)₂) en een oplossing van calciumchloride (CaCl₂).
CaO + MgO (dolime) + 2 H₂O + Mg²⁺ → 2 Mg(OH)₂ + Ca²⁺ (reactie 1)$$, 'inline'),
  ('1ddedb7b-e40f-4ac6-9277-0cbac9d23b49', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$Mg(OH)2 bezinkt — reactor (R) en scheidingsruimte (S)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context8.png$$,
   $$Het Mg(OH)₂ bezinkt. Het grootste deel van het Mg(OH)₂ wordt in een reactor (R) ontleed tot MgO en water. Een klein deel van het Mg(OH)₂ wordt afgevoerd en verkocht. De CaCl₂-oplossing wordt in een scheidingsruimte (S) ingedampt.$$, 'inline'),
  ('efb96df0-6299-47a8-9089-8bbc9b3a23e3', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$figuur 2 — bezinkbak (basisschema)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context9.png$$,
   $$In figuur 2 en op de uitwerkbijlage is een blokschema van dit proces schematisch en onvolledig weergegeven. In dit proces worden de volgende stoffen geproduceerd: CaCl₂, Mg(OH)₂ en MgO.
figuur 2: basisschema met de bezinkbak: MgCl₂-oplossing komt de bezinkbak in via twee pijlen, er gaat een stofstroom naar rechts uit de bezinkbak en een stofstroom naar beneden/opzij; reactor (R) en scheidingsruimte (S) ontbreken nog in het schema.$$, 'inline'),
  ('f573a64b-9493-4a8c-b7f9-d46d7c3a1ca4', 'ca54f250-1094-48a3-bb44-5b8956e25957', $$uitwerkbijlage vraag 14 — onvolledig blokschema bezinkbak$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-producten-uit-bischofiet-context10.png$$,
   $$onvolledig blokschema op de uitwerkbijlage: MgCl₂-oplossing stroomt de bezinkbak in; uit de bezinkbak vertrekken twee stofstromen (naar boven-rechts en naar beneden); de leerling moet de ontbrekende reactor (R) en scheidingsruimte (S) tekenen, de ontbrekende pijlen tekenen, en de nummers van de stoffen (1 vast CaCl₂, 2 vast Mg(OH)₂, 3 vast MgO, 4 CaCl₂-oplossing, 5 vast dolime, 6 water) bij de juiste pijl noteren.$$, 'uitwerkbijlage'),
  ('718d2924-786a-4fab-a0cd-62a99d2bad36', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$fosfine intro en tekstfragment — meting op schip in Utrecht (bron: nos.nl)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context1.png$$,
   $$Fosfine (PH₃) is een brandbaar en zeer giftig gas. Het wordt gebruikt voor bestrijding van ongedierte, bijvoorbeeld in de lading van een schip.
tekstfragment: Bij een meting op een schip in Utrecht werden concentraties fosfine gemeten van meer dan 300 massa-ppm. Voor mensen is de stof al gevaarlijk vanaf een concentratie van 0,5 massa-ppm. Fosfine wordt niet als gas in het ruim van een schip verspreid, maar er worden pillen met magnesiumfosfide in het ruim van het schip gelegd. Het magnesiumfosfide in de pillen zal langzaam reageren met waterdamp, waarbij gasvormige fosfine wordt gevormd. (naar: nos.nl, zomer 2021)$$, 'inline'),
  ('870dc0dd-4b20-44f6-89ae-e359bc693308', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$verhoudingsformule magnesiumfosfide Mg3P2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context2.png$$,
   $$De verhoudingsformule van magnesiumfosfide is Mg₃P₂.$$, 'inline'),
  ('0d403e8a-c1a7-4d0a-9fd9-cad40d8f247b', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$reactie magnesiumfosfide met waterdamp — producten PH3 en Mg(OH)2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context3.png$$,
   $$Bij de reactie van magnesiumfosfide met waterdamp ontstaan uitsluitend de stoffen fosfine (PH₃) en magnesiumhydroxide (Mg(OH)₂).$$, 'inline'),
  ('1fc0aa72-5158-41b7-89bb-ec05f4eb21a3', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$leverancier — 0,20 gram fosfine per pil$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context4.png$$,
   $$Op de website van een leverancier van magnesiumfosfidepillen staat het volgende vermeld:
1 magnesiumfosfidepil zal maximaal 0,20 gram fosfine vormen.$$, 'inline'),
  ('a4e97217-c9c5-4519-aab6-31fa2cf23b44', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$H-zinnen fosfine — veiligheidskaart$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context5.png$$,
   $$Een veiligheidsinspecteur die de lading van een binnenvaartschip controleert, moet rekening houden met de aanwezigheid en bijbehorende gevaren van fosfine. Op de veiligheidskaart van fosfine staan de volgende H-zinnen vermeld: H220, H250, H280, H314, H318, H330, H400. Niet alle H-zinnen zijn van belang voor de gezondheid van de veiligheidsinspecteur.$$, 'inline'),
  ('a32558e5-b0ed-4359-a293-609deba79b8c', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$brandbaarheid en spontane ontbranding — vorming fosforzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context6.png$$,
   $$Ook de brandbaarheid van fosfine kan tot gevaarlijke situaties leiden. Als de concentratie fosfine in de lucht hoog genoeg wordt, kan fosfine spontaan ontbranden. Bij deze verbrandingsreactie wordt uitsluitend fosforzuur gevormd.$$, 'inline'),
  ('6f9670da-185d-424c-b553-53b1f24373e1', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$exotherme vorming fosfine en ontleding ammoniumcarbamaat — reactie 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context7.png$$,
   $$Spontane ontbranding komt doordat de reactie waarbij fosfine ontstaat exotherm is. De temperatuur stijgt als gevolg hiervan, waardoor fosfine kan ontbranden. Daarom bevatten magnesiumfosfidepillen ammoniumcarbamaat (NH₂CO₂NH₄). De aanwezigheid van ammoniumcarbamaat in de pillen verkleint de kans op spontane ontbranding. Als de temperatuur boven de 60 °C komt, zal ammoniumcarbamaat ontleden volgens reactie 1.
NH₂CO₂NH₄ (s) → 2 NH₃ (g) + CO₂ (g) (reactie 1)$$, 'inline'),
  ('7600e4cd-1853-4c3e-a82b-ed2c6f5c72a7', 'a66902de-3d0b-4fd9-bb26-5bb03bb6ccf9', $$twee manieren waarop ontleding ammoniumcarbamaat ontbranding verkleint$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-fosfine-in-binnenvaartschepen-context8.png$$,
   $$De kans op spontane ontbranding van fosfine is het grootst dicht bij de pil, waar de fosfineconcentraties hoog kunnen oplopen. De ontleding van ammoniumcarbamaat (reactie 1) verkleint deze kans op twee manieren:
– Manier 1: de ontleding van ammoniumcarbamaat is endotherm.
– Manier 2: bij de ontleding van ammoniumcarbamaat ontstaan gassen.$$, 'inline'),
  ('31df0b8b-97fe-4df9-aaf9-fdff6bf8335f', 'a273f028-c105-4f58-a310-607c26e40de2', $$inleiding — uraan toepassingen en isotoop U-235$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-uraan-uit-zeewater-context1.png$$,
   $$Uraan kent verschillende toepassingen. Het bekendst is de toepassing als energiebron voor kerncentrales. Hiervoor is de isotoop U-235 nodig.$$, 'inline'),
  ('6adb4485-2db4-47b5-9b5a-f7ed7cf71758', 'a273f028-c105-4f58-a310-607c26e40de2', $$uraanwinning uit erts vs. zeewater — jaarlijkse behoefte en gehalte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-uraan-uit-zeewater-context2.png$$,
   $$Tot nu toe wordt uraan in de vorm van erts afgegraven uit mijnen. Bij een jaarlijkse wereldwijde behoefte van 6,0·10⁷ kg uraan zullen deze mijnen een voorraad uraan hebben voor slechts 80 jaar. Zeewater is een veel grotere bron van uraan. Winning van uraan uit zeewater staat daarom in de belangstelling. Een probleem hierbij is echter dat het gehalte in zeewater laag is: 3,38·10⁻⁹ kg uraan per L.$$, 'inline'),
  ('6981e972-1ea2-4830-a12e-2cc747e0cb19', 'a273f028-c105-4f58-a310-607c26e40de2', $$UO2^2+-ion en omiganan — peptide dat water bindt$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-uraan-uit-zeewater-context3.png$$,
   $$In zeewater is uraan vooral aanwezig in de vorm van het UO₂²⁺-ion. De winning van uraan uit zeewater is nog experimenteel. Voor deze winning worden polymeren gebruikt die in staat zijn om UO₂²⁺-ionen te binden.
De basis van dit polymeer is het peptide omiganan. De aminozuurvolgorde van omiganan is als volgt:
Ile-Leu-Arg-Trp-Pro-Trp-Trp-Pro-Trp-Arg-Arg-Lys (omiganan)
Omiganan is in staat om water te binden.$$, 'inline'),
  ('9dd105f0-f6bf-4827-8566-ff0a4aa3ba95', 'a273f028-c105-4f58-a310-607c26e40de2', $$hydrogel — onderzoeksopzet stappen 1 t/m 4 (UO2^2+-binding)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-uraan-uit-zeewater-context4.png$$,
   $$Als omiganan gecrosslinkt wordt, ontstaat een hydrogel. Een hydrogel is een vaste, onoplosbare stof die gebonden water bevat. Behalve water kan deze hydrogel ook UO₂²⁺-ionen uit het zeewater binden. Zo kan de hydrogel UO₂²⁺-ionen uit zeewater halen. Andere ionen in zeewater worden namelijk niet of in veel mindere mate aan de hydrogel gebonden.
Onderzoekers wilden de massa aan UO₂²⁺-ionen bepalen die per gram hydrogel gebonden kan worden. Dit onderzoek werd als volgt uitgevoerd:
Stap 1: Een bepaalde hoeveelheid hydrogel werd in een bak gelegd waar zeewater doorheen werd gepompt.
Stap 2: Na enkele weken werd de hydrogel uit de bak met zeewater gehaald en spoelden de onderzoekers de hydrogel met gedestilleerd water.
Stap 3: De hydrogel werd in een oplossing van de stof EDTA gelegd. Hierdoor kwamen de UO₂²⁺-ionen weer los van de hydrogel en bonden aan EDTA-ionen.
Stap 4: UO₂²⁺-ionen werden weer losgemaakt van EDTA-ionen en de massa van de UO₂²⁺-ionen werd bepaald.$$, 'inline'),
  ('0c11d8b1-1b1d-4eaa-ad5e-4dd0677c8986', 'a273f028-c105-4f58-a310-607c26e40de2', $$figuur 1 — structuurformule Na2-EDTA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-uraan-uit-zeewater-context5.png$$,
   $$In stap 3 kwamen de UO₂²⁺-ionen los van de hydrogel omdat deze ionen beter binden met EDTA-ionen dan met de hydrogel. In het onderzoek werd een oplossing van het zout Na₂-EDTA gebruikt. In figuur 1 is de structuurformule van de vaste stof Na₂-EDTA weergegeven.
figuur 1: structuurformule van Na₂-EDTA — een centraal N-CH₂-CH₂-N-fragment met aan elk N-atoom twee -CH₂-C(=O)-O-groepen; twee van deze vier zuurgroepen zijn vrije carbonzuurgroepen (-C(=O)-OH), de andere twee zijn natriumzouten (-C(=O)-O⁻Na⁺).$$, 'inline'),
  ('a88e83e7-c17c-401a-9bf5-b471405cab67', 'a273f028-c105-4f58-a310-607c26e40de2', $$EDTA-ionen Y2- omzetten naar Y4- via pH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-uraan-uit-zeewater-context6.png$$,
   $$Na oplossen van Na₂-EDTA in water ontstaan vrije EDTA-ionen. Deze ionen worden weergegeven met de formule Y²⁻. Door de pH te veranderen kan men Y²⁻-ionen omzetten tot Y⁴⁻-ionen. Per Y⁴⁻-ion kan één UO₂²⁺-ion worden gebonden.$$, 'inline'),
  ('de1e9847-b071-44e5-b761-3409570f1837', 'a273f028-c105-4f58-a310-607c26e40de2', $$hydrogel hergebruik — 2,99·10⁻⁵ mol UO2^2+ per gram$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-uraan-uit-zeewater-context7.png$$,
   $$De hydrogel kan na stap 3 worden hergebruikt. Na het uitvoeren van de stappen 1 tot en met 4 werd per gram gebruikte hydrogel 2,99·10⁻⁵ mol UO₂²⁺-ionen verkregen. Dit proces is voor verbetering vatbaar, omdat er erg grote hoeveelheden hydrogel nodig zijn om de wereldwijde jaarlijkse behoefte aan uraan voor kerncentrales te kunnen leveren.$$, 'inline'),
  ('f941a2aa-f17c-42bb-92ed-c90a1b3022a6', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$intro en reactie 1 — vorming ammoniak uit waterstof en stikstof$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context1.png$$,
   $$De meeste auto’s met een brandstofcel gebruiken waterstof als brandstof. Om een ‘volle’ tank waterstof te krijgen, moet waterstof onder zeer hoge druk worden opgeslagen. Dit opslaan onder hoge druk is niet nodig als waterstof met stikstof uit de lucht eerst wordt omgezet tot ammoniak.
N₂ + 3 H₂ → 2 NH₃ (reactie 1)$$, 'inline'),
  ('7b60099f-f842-4b48-a8fe-636b8d2ee14f', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$figuur 1 — schema ammoniak-brandstofcel$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context2.png$$,
   $$Ammoniak is ook geschikt als brandstof in een brandstofcel en kan gemakkelijker vloeibaar gemaakt worden dan waterstof. In figuur 1 is een ammoniak-brandstofcel schematisch weergegeven.
figuur 1: schema van de ammoniak-brandstofcel met een C-MnO₂-elektrode en een C-Ni-elektrode, gescheiden door een membraan waar OH⁻-ionen doorheen bewegen (van de C-MnO₂- naar de C-Ni-elektrode), met een lampje in de buitenste stroomkring; bij de C-MnO₂-elektrode gaat H₂O + lucht (met O₂) naar binnen en komt H₂O + lucht (zonder O₂) naar buiten; bij de C-Ni-elektrode gaat NH₃ naar binnen en komt H₂O + N₂ naar buiten.$$, 'inline'),
  ('71a7305e-5417-4bfd-b75c-96bcb7b1d06a', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$halfreactie a — zuurstof aan C-MnO2-elektrode$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context3.png$$,
   $$In deze brandstofcel reageert zuurstof aan de C-MnO₂-elektrode volgens halfreactie a:
O₂ + 2 H₂O + 4 e⁻ → 4 OH⁻ (halfreactie a)$$, 'inline'),
  ('82d7463f-6227-4b6e-a730-d46df7b36f5d', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$halfreactie b — ammoniak aan C-Ni-elektrode (onvolledig)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context4.png$$,
   $$Aan de C-Ni-elektrode reageert ammoniak volgens halfreactie b. Halfreactie b is hieronder onvolledig weergegeven: de coëfficiënten ontbreken.
NH₃ + OH⁻ → N₂ + H₂O + e⁻ (halfreactie b)$$, 'inline'),
  ('3fd7d78f-cf17-4fdd-bd39-dcb1776c6c88', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$C-MnO2-elektrode — 20 massaprocent MnO2 als katalysator$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context5.png$$,
   $$De C-MnO₂-elektrode bevat 20 massaprocent MnO₂. MnO₂ dient als katalysator en niet als geleidend materiaal.$$, 'inline'),
  ('72a3cbab-28dd-4142-83a1-362c4445a22d', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$twee stappen — waterstof-brandstofcel vs. ammoniak-brandstofcel$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context6.png$$,
   $$In een waterstof-brandstofcel reageren waterstof en zuurstof tot water. Het gebruik van ammoniak als brandstof komt neer op dezelfde reactie, maar dan in twee stappen.
Stap 1: Waterstof en stikstof worden omgezet tot ammoniak (reactie 1).
Stap 2: In een ammoniak-brandstofcel reageren ammoniak en zuurstof tot stikstof en water.$$, 'inline'),
  ('dfcf192a-245d-4b7d-972f-265da013e357', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$figuur 2 — energiediagram ΔE1, ΔE2, ΔE3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context7.png$$,
   $$In figuur 2 zijn de energie-effecten in de waterstof-brandstofcel (ΔE₁) en in de ammoniak-brandstofcel (ΔE₃) weergegeven in één energiediagram.
figuur 2: energiediagram met op de linkerhelft (waterstof-brandstofcel) het energieniveau van H₂O + N₂ onderaan en H₂ + O₂ + N₂ bovenaan, verbonden door pijl ΔE₁ (omhoog); op de rechterhelft (ammoniak-brandstofcel) het energieniveau van NH₃ + O₂ (verbonden met het niveau van H₂ + O₂ + N₂ via pijl ΔE₂ omlaag) en daaronder het energieniveau van H₂O + N₂, verbonden door pijl ΔE₃ (omlaag).$$, 'inline'),
  ('4fa9b079-c1f0-489d-afcc-a1b278a48c86', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$conclusie — ammoniak-brandstofcel levert minder energie per mol waterstof$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context8.png$$,
   $$Uit figuur 2 blijkt dat de ammoniak-brandstofcel minder energie levert per mol waterstof dan de waterstof-brandstofcel.$$, 'inline'),
  ('268a2a40-2b53-4108-9535-abea7cb42906', '876ca20e-5aa9-4136-9568-d16de521f7fb', $$verbranding ammoniak — mogelijke vorming stikstofoxides$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-ammoniak-brandstofcel-context9.png$$,
   $$Stoffen die reageren in een brandstofcel, zouden ook direct verbrand kunnen worden. Bij de verbranding van ammoniak ontstaan dan niet alleen N₂ en H₂O; onder bepaalde omstandigheden kunnen dan ook stikstofoxides gevormd worden. Stikstofoxides hebben een negatief effect op het milieu.$$, 'inline');
insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('eab1c5b9-b9ab-4a10-994f-8322a2b35812', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', 1,
   '[{"domain": "Reacties", "subdomain": "Chemische processen"}]'::jsonb,
   '["glucose", "ethanol", "koolstofdioxide", "gisting", "molecuulformule", "reactievergelijking"]'::jsonb,
   $$Opstellen van de reactievergelijking voor de omzetting van glucose tot ethanol en koolstofdioxide in molecuulformules.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-vraag1.png$$, $$Geef de vergelijking voor deze omzetting in molecuulformules.$$, array['3333dc5a-7e11-4ba7-8cc0-9bcb53b8a728']::uuid[]),
  ('72488e2f-0898-4098-b55c-587ec83df3e7', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', 2,
   '[{"domain": "Chemie van het leven", "subdomain": "Structuur en functie"}]'::jsonb,
   '["aminozuur", "peptidebinding", "tripeptide", "restgroep", "cysteïne", "glycine"]'::jsonb,
   $$Benoemen van een aminozuur-eenheid in een tripeptide en verklaren waarom bepaalde restgroepen geen peptidebinding kunnen vormen.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-vraag2.png$$, $$Voer de volgende opdrachten uit:
– Geef de naam van deze eerste aminozuur-eenheid. Gebruik Binas-tabel 67H1 of ScienceData-tabel 13.7c.
– Licht toe waarom de restgroepen van cysteïne en glycine niet via een peptidebinding kunnen koppelen en de restgroep van de eerste aminozuur-eenheid wel.$$, array['4861aa0a-cdbd-414d-a125-c00c36fd7787', 'f1bd2246-0964-41a8-b5a1-70a1fd4d638a']::uuid[]),
  ('43d6236a-53b5-4e85-8b56-834e1bacc0a6', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', 3,
   '[{"domain": "Chemie van het leven", "subdomain": "Structuur en functie"}]'::jsonb,
   '["enzym", "specificiteit", "substraat", "biokatalysator", "enzymwerking"]'::jsonb,
   $$Verklaren waarom een enzym dat één stap katalyseert niet ook een volgende stap kan katalyseren, op basis van enzymspecificiteit.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-vraag3.png$$, $$Geef een verklaring waarom het enzym dat stap 1 katalyseert niet ook stap 2 kan katalyseren.$$, array['e1baffcb-0c24-4c92-ae79-34c1113813fa']::uuid[]),
  ('2e10c376-3a8c-48fd-9e6f-e4966ed3bd47', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', 4,
   '[{"domain": "Rekenen en analyse", "subdomain": "Chemische vakmethodes"}]'::jsonb,
   '["scheidingsmethode", "stofeigenschap", "bezinken", "centrifugeren", "gistcellen"]'::jsonb,
   $$Benoemen van een alternatieve scheidingsmethode voor het scheiden van gist van wijn en het onderliggende stofeigenschapverschil.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-vraag4.png$$, $$Geef de naam van de andere scheidingsmethode en geef aan op welk verschil in stofeigenschap deze scheidingsmethode berust.
Noteer je antwoord als volgt:
scheidingsmethode: …
verschil in stofeigenschap: …$$, array['18f7b2bf-c66b-4774-855d-c6a1e3bdc17f']::uuid[]),
  ('8366fa5c-a364-4605-a86e-e92c6ad1a29c', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', 5,
   '[{"domain": "Reacties", "subdomain": "Classificatie van reacties"}]'::jsonb,
   '["hydrolyse", "ester", "structuurformule", "uitwerkbijlage", "reactievergelijking"]'::jsonb,
   $$Voltooien van de hydrolysevergelijking van de ester 3-MHA met structuurformules.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-vraag5.png$$, $$Maak op de uitwerkbijlage de vergelijking van de hydrolyse van 3-MHA compleet. Gebruik structuurformules voor koolstofverbindingen.$$, array['812b1214-94ba-4adf-8934-d8a45524f4aa', '593e81be-6c9d-40e5-bd78-85df5f30f1ee', '0feed504-c1d2-4678-8433-d98fb531a35e']::uuid[]),
  ('1da92dfc-d3aa-4119-b731-9bb8f2fcd041', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', 6,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["oplosbaarheid", "waterstofbrug", "polaire binding", "hydrofiel", "microniveau"]'::jsonb,
   $$Verklaren op microniveau welke van twee geurstoffen beter in wijn oplost en dit toetsen aan een hypothese over geurdrempel.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-vraag6.png$$, $$Voer de volgende opdrachten uit:
– Leg uit op microniveau welke geurstof beter in wijn oplost: 3-MHA of 3-MH. Gebruik de structuurformules uit figuur 3 en verwerk in je antwoord het soort binding dat hierbij betrokken is.
– Geef aan of Danilo’s hypothese hiermee in overeenstemming is.$$, array['812b1214-94ba-4adf-8934-d8a45524f4aa', 'b08e4f23-ea55-4d12-bed1-58f120cc7b70', '232408e5-d8aa-4694-bffb-ccccd5ff86f7']::uuid[]),
  ('fa9beaf5-c49b-46ba-9213-eab84a7876c2', 'fdd8483c-2b84-4318-b2b2-f7bd05ac4aad', 7,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["OAV", "concentratie", "massaverhouding", "molverhouding", "omzetting"]'::jsonb,
   $$Berekenen van de nieuwe totale Odour Activity Value na gedeeltelijke omzetting van 3-MHA in 3-MH.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2024-ii-passievruchtaroma-in-sauvignon-blanc-vraag7.png$$, $$Bereken de nieuwe totale OAV.
Gebruik de volgende gegevens:
– waarden uit tabel 1;
– uit 1,3 gram 3-MHA wordt 1,0 gram 3-MH gevormd.$$, array['11e20b9f-1a2b-4788-ae01-ee9342306d2f', '2aadae01-859b-4453-ab4e-dea7c5c7ce71', 'caf9d3f1-1365-4986-bfae-4b0392449c5e']::uuid[]),
  ('6338a492-2435-4b4f-a904-258049295f09', 'ca54f250-1094-48a3-bb44-5b8956e25957', 8,
